<?php
declare(strict_types=1);
function validate_interest(array $input,array $definition):array{$fields=form_field_by_id($definition);$errors=[];$clean=[];foreach($input as $k=>$_)if(!in_array($k,array_merge(array_keys($fields),['_csrf','_website','_started_at']),true))$errors[$k]='Unexpected field.';foreach($fields as $id=>$field){$v=$input[$id]??'';if(is_array($v)){$errors[$id]='Invalid value.';continue;}$v=trim((string)$v);if(($field['required']??false)&&$v===''){$errors[$id]='This field is required.';continue;}if($v===''){$clean[$id]='';continue;}if(strlen($v)>4000||preg_match('/<[^>]*>|javascript:|on\\w+\\s*=/i',$v)){$errors[$id]='Invalid value.';continue;}if($field['type']==='email'&&!filter_var($v,FILTER_VALIDATE_EMAIL))$errors[$id]='Enter a valid email address.';if($field['type']==='number'&&!is_numeric($v))$errors[$id]='Enter a numeric value.';if(in_array($field['type'],['radio','select'],true)&&!in_array($v,array_column($field['options']??[],'value'),true))$errors[$id]='Invalid option.';if(in_array($field['type'],['checkbox','consent'],true)&&$v!=='1')$errors[$id]='Please confirm this field.';$clean[$id]=$v;}return [$clean,$errors];}
